import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Day 21: Systemd & Init Systems","description":"","frontmatter":{},"headers":[],"relativePath":"day21-init-systems-and-systemd.md","filePath":"day21-init-systems-and-systemd.md"}'),n={name:"day21-init-systems-and-systemd.md"};function l(h,s,p,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="day-21-systemd-init-systems" tabindex="-1">Day 21: Systemd &amp; Init Systems <a class="header-anchor" href="#day-21-systemd-init-systems" aria-label="Permalink to &quot;Day 21: Systemd &amp; Init Systems&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain what PID 1 is and the role of an Init System in Linux</li><li>Switch a Yocto build from SysVinit to Systemd</li><li>Write a Systemd <code>.service</code> file to auto-start a custom C application on boot</li><li>Package the service file in a Yocto recipe using <code>systemd.bbclass</code></li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day20-uboot-tftp-nfs-booting.html">Day 20: Bootloaders: U-Boot &amp; Network Booting</a></li></ul></div><hr><h2 id="_1-what-happens-after-the-kernel-boots" tabindex="-1">1. What happens after the Kernel boots? <a class="header-anchor" href="#_1-what-happens-after-the-kernel-boots" aria-label="Permalink to &quot;1. What happens after the Kernel boots?&quot;">​</a></h2><p>In Day 3, we traced the boot sequence up to the point where the Linux Kernel takes over.</p><p>Once the Kernel finishes initializing the hardware drivers, it mounts the root filesystem (from the SD card or NFS) and looks for the very first user-space program to execute. This program is called the <strong>Init System</strong>.</p><p>The Init System is assigned Process ID 1 (<strong>PID 1</strong>). Its sole job is to spawn every other process in the system (the network manager, the SSH server, the graphical interface, and your custom applications).</p><h3 id="sysvinit-vs-systemd" tabindex="-1">SysVinit vs Systemd <a class="header-anchor" href="#sysvinit-vs-systemd" aria-label="Permalink to &quot;SysVinit vs Systemd&quot;">​</a></h3><ul><li><strong>SysVinit:</strong> The traditional UNIX init system. It uses sequential bash scripts located in <code>/etc/init.d/</code> to start services one by one. It is very simple and lightweight, which is why it is the default init system in Yocto&#39;s <code>core-image-minimal</code>.</li><li><strong>Systemd:</strong> The modern Linux standard (used by Ubuntu, Debian, RedHat). It starts services in parallel, tracks their dependencies, manages logging (journald), and restarts applications if they crash. It is complex and heavy, but incredibly powerful for production embedded devices.</li></ul><hr><h2 id="_2-switching-yocto-to-systemd" tabindex="-1">2. Switching Yocto to Systemd <a class="header-anchor" href="#_2-switching-yocto-to-systemd" aria-label="Permalink to &quot;2. Switching Yocto to Systemd&quot;">​</a></h2><p>Because Systemd offers crash-recovery and dependency management, most commercial embedded Linux products use it over SysVinit.</p><p>To switch your Yocto build to use Systemd, you modify your <code>conf/local.conf</code> (or your custom distribution configuration):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In conf/local.conf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use systemd as the init manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INIT_MANAGER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;systemd&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prevent sysvinit scripts from being installed if both exist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DISTRO_FEATURES_BACKFILL_CONSIDERED</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sysvinit&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ensure journald (logging) is persistent across reboots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VOLATILE_LOG_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;no&quot;</span></span></code></pre></div><hr><h2 id="_3-auto-starting-an-application-on-boot" tabindex="-1">3. Auto-Starting an Application on Boot <a class="header-anchor" href="#_3-auto-starting-an-application-on-boot" aria-label="Permalink to &quot;3. Auto-Starting an Application on Boot&quot;">​</a></h2><p>Let&#39;s say you want the <code>helloworld</code> C application we built in Day 8 to start automatically the moment the board turns on, and restart automatically if it crashes.</p><h3 id="step-1-write-a-systemd-service-file" tabindex="-1">Step 1: Write a Systemd Service File <a class="header-anchor" href="#step-1-write-a-systemd-service-file" aria-label="Permalink to &quot;Step 1: Write a Systemd Service File&quot;">​</a></h3><p>Create a file named <code>helloworld.service</code> in your recipe&#39;s <code>files/</code> directory:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># meta-custom/recipes-example/helloworld/files/helloworld.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Hello World Daemon</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The path to our binary</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/bin/helloworld</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If the app crashes, restart it automatically</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RestartSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start this app when the multi-user system is ready</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><h3 id="step-2-update-the-yocto-recipe" tabindex="-1">Step 2: Update the Yocto Recipe <a class="header-anchor" href="#step-2-update-the-yocto-recipe" aria-label="Permalink to &quot;Step 2: Update the Yocto Recipe&quot;">​</a></h3><p>We need to tell Yocto to install this <code>.service</code> file and register it with Systemd.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># meta-custom/recipes-example/helloworld/helloworld_1.0.bb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;A simple Hello World C application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LICENSE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LIC_FILES_CHKSUM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file://helloworld.c </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           file://helloworld.service </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          &quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WORKDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inherit the systemd class to handle the complex registration logic</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tell the class the name of our service file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SYSTEMD_SERVICE:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;helloworld.service&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable it to start automatically on boot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SYSTEMD_AUTO_ENABLE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;enable&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    \${CC} \${CFLAGS} \${LDFLAGS} </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">helloworld.c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Install the binary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${bindir}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${bindir}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Install the systemd service file into the correct directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${systemd_system_unitdir}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${WORKDIR}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/helloworld.service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${D}\${systemd_system_unitdir}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_4-troubleshooting-systemd-on-the-target" tabindex="-1">4. Troubleshooting Systemd on the Target <a class="header-anchor" href="#_4-troubleshooting-systemd-on-the-target" aria-label="Permalink to &quot;4. Troubleshooting Systemd on the Target&quot;">​</a></h2><p>Once you boot your image, you interact with Systemd using the <code>systemctl</code> and <code>journalctl</code> commands.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the status of your app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop the app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View the log output (e.g., the printf statements from your C code)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld.service</span></span></code></pre></div><hr><h2 id="_5-course-completion-🎓" tabindex="-1">5. Course Completion! 🎓 <a class="header-anchor" href="#_5-course-completion-🎓" aria-label="Permalink to &quot;5. Course Completion! 🎓&quot;">​</a></h2><p>You have now reached the end of the Advanced Deep Dives section!</p><p>You possess the comprehensive knowledge required to take a bare metal board, configure the hardware (Device Trees), compile a tailored kernel (Menuconfig), load it rapidly over the network (U-Boot/TFTP), and construct a resilient, production-ready filesystem (Yocto/Systemd).</p><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day20-uboot-tftp-nfs-booting">← Day 20: U-Boot &amp; Network Booting</a><a href="/cheat-sheet">BitBake Cheat Sheet →</a></div>`,33)])])}const y=i(n,[["render",l]]);export{c as __pageData,y as default};
